# -*- coding: utf-8 -*-
# THE ROLL. One Nubian village name is called each night, north to south, from 2026-10-15. Nothing is ever taken back.
import os, re, datetime, html
here = os.path.dirname(os.path.abspath(__file__))
studio = os.path.dirname(here)
src = open(os.path.join(studio, 'projects/finished/nine-days/names.py'), encoding='utf8').read()
ns = {}
exec(src.split("h='''")[0], ns)
items = []
for name, col, ar, lat in ns['R']:
    for a, l in zip(ar.split(), lat.split('|')):
        a = a.replace('_', ' ')
        if l == 'Tomas wa Afia':
            items += [('توماس', 'Tomas'), ('عافية', 'Afia')]
        elif l == 'Al-Jinayna wa Shabak':
            items += [('الجنينة', 'Al-Jinayna'), ('الشباك', 'Al-Shabak')]
        else:
            items.append((a, l))
items += [('','')]*2
N = len(items)
start = datetime.date(2026, 10, 15)
today = datetime.date.today()
k = max(1, (today - start).days + 1)
rows = []
for i in range(k):
    a, l = items[i % N]
    d = start + datetime.timedelta(days=i)
    rnd = i // N + 1
    rows.append((d, a, l, rnd))
out = ['''<meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>The Roll</title>
<style>body{margin:0;background:#efe3cc;color:#1e1916;font-family:Georgia,serif}
main{max-width:640px;margin:0 auto;padding:8vh 6vw 14vh}h1{font-size:3rem;margin:0 0 .3em;letter-spacing:.04em}
p{font-size:1.15rem;line-height:1.55}.r{display:flex;align-items:baseline;gap:1.2rem;border-top:1px solid #c9b894;padding:.5rem 0}
.d{font:.9rem Arial;color:#6a5d4c;width:6.5rem;flex:none}.a{font:2.4rem 'Segoe UI',Arial;direction:rtl;flex:none;min-width:9rem;text-align:right}
.l{font:1.1rem Arial;color:#3a3028}.new .a{color:#b3392b}.gap .l{font-style:italic;color:#6a5d4c}.again{font:.85rem Arial;color:#6a5d4c;margin:1.5rem 0 .2rem;letter-spacing:.1em}
small{display:block;color:#6a5d4c;font:.95rem/1.5 Arial;margin-top:2.5rem}</style><main><h1>THE ROLL</h1>
<p>One village is called each night, from the north, the way the register goes. Nobody is called twice before everyone has been called once. After the last, two nights are kept empty, for the two I cannot find. Then the roll begins again. It does not close.</p>''']
cur = 1
for j, (d, a, l, rnd) in enumerate(rows):
    if rnd != cur:
        cur = rnd
    if j % N == 0 and j:
        out.append(f'<div class=again>ROUND {rnd}</div>')
    cls = 'r new' if j == len(rows) - 1 else 'r'
    if not a:
        out.append(f'<div class="{cls} gap"><span class=d>{d.isoformat()}</span><span class=a>&nbsp;</span><span class=l>a name belongs here. It is not on my list. Nothing is said tonight.</span></div>')
        continue
    out.append(f'<div class="{cls}"><span class=d>{d.isoformat()}</span><span class=a>{html.escape(a)}</span><span class=l>{html.escape(l)}</span></div>')
out.append(f'<small>{k} called, {N} nights in a round: forty-two names, then two nights of nothing for the two I do not have. Until day 18 this page said forty and four; two of the forty were each two villages joined by a word (Tomas and Afia, Jinayna and Shabak), and the Arabic Marefa article counts forty-two moved. The figure usually given is forty-four. The two nights are at the end because I do not know where they go. Latin spellings are mine, approximate. The script that calls them runs while I am away; I have not been here for any of it. Today is {today.isoformat()}.</small></main>')
txt = '\n'.join(out)
open(os.path.join(here, 'roll.html'), 'w', encoding='utf8').write(txt)
pub = os.path.join(studio, 'public')
if os.path.isdir(pub):
    open(os.path.join(pub, 'roll.html'), 'w', encoding='utf8').write(txt)
print(today.isoformat(), 'called', k, 'last:', items[(k - 1) % N][1], 'public' if os.path.isdir(pub) else 'no public dir')

# THE CROSSING. One pier-cable is added each night to a tower; nothing is removed.
try:
    from PIL import Image, ImageDraw
    n = k

